package algorithms.linkedlist;

/**
 * Linked List Core Operations — Java
 */
public class LinkedListOperations {

    static class ListNode {
        int val; ListNode next;
        ListNode(int val) { this.val = val; }
        ListNode(int val, ListNode next) { this.val = val; this.next = next; }
    }

    // Reverse a linked list — O(n) time, O(1) space
    public static ListNode reverseList(ListNode head) {
        ListNode prev = null, curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }

    // Recursive reverse
    public static ListNode reverseRecursive(ListNode head) {
        if (head == null || head.next == null) return head;
        ListNode newHead = reverseRecursive(head.next);
        head.next.next = head;
        head.next = null;
        return newHead;
    }

    // Floyd's cycle detection — O(n) time, O(1) space
    public static boolean hasCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }

    // Find middle node (slow/fast pointers)
    public static ListNode findMiddle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    // Merge two sorted linked lists — O(n+m)
    public static ListNode mergeTwoSorted(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0), curr = dummy;
        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) { curr.next = l1; l1 = l1.next; }
            else                  { curr.next = l2; l2 = l2.next; }
            curr = curr.next;
        }
        curr.next = l1 != null ? l1 : l2;
        return dummy.next;
    }

    // Remove nth node from end — O(n) one-pass
    public static ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode fast = dummy, slow = dummy;
        for (int i = 0; i <= n; i++) fast = fast.next;
        while (fast != null) { slow = slow.next; fast = fast.next; }
        slow.next = slow.next.next;
        return dummy.next;
    }

    // Rotate list by k places
    public static ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;
        int len = 1;
        ListNode tail = head;
        while (tail.next != null) { tail = tail.next; len++; }
        tail.next = head; // make circular
        k = k % len;
        int stepsToNewTail = len - k;
        ListNode newTail = head;
        for (int i = 1; i < stepsToNewTail; i++) newTail = newTail.next;
        ListNode newHead = newTail.next;
        newTail.next = null;
        return newHead;
    }

    // Helper: build list from array
    static ListNode of(int... vals) {
        ListNode dummy = new ListNode(0), curr = dummy;
        for (int v : vals) { curr.next = new ListNode(v); curr = curr.next; }
        return dummy.next;
    }
    // Helper: list to string
    static String print(ListNode head) {
        StringBuilder sb = new StringBuilder();
        while (head != null) { sb.append(head.val); if (head.next != null) sb.append(" -> "); head = head.next; }
        return sb.toString();
    }

    public static void main(String[] args) {
        ListNode list = of(1, 2, 3, 4, 5);
        System.out.println("Original: " + print(list));               // 1 -> 2 -> 3 -> 4 -> 5
        System.out.println("Middle:   " + findMiddle(list).val);      // 3
        System.out.println("Reversed: " + print(reverseList(list)));  // 5 -> 4 -> 3 -> 2 -> 1

        ListNode l1 = of(1, 3, 5), l2 = of(2, 4, 6);
        System.out.println("Merged:   " + print(mergeTwoSorted(l1, l2))); // 1 -> 2 -> 3 -> 4 -> 5 -> 6

        System.out.println("hasCycle: " + hasCycle(of(1, 2, 3)));  // false
    }
}

package snippets.java.http;

import java.net.URI;
import java.net.http.*;
import java.net.http.HttpRequest.BodyPublishers;
import java.net.http.HttpResponse.BodyHandlers;
import java.time.Duration;
import java.util.concurrent.*;
import java.util.List;

/**
 * Java 11+ HttpClient — Modern HTTP in Java
 * Built-in, async, HTTP/2 support, zero extra dependencies.
 */
public class JavaHttpClient {

    private static final HttpClient client = HttpClient.newBuilder()
        .version(HttpClient.Version.HTTP_2)
        .connectTimeout(Duration.ofSeconds(10))
        .followRedirects(HttpClient.Redirect.NORMAL)
        .build();

    // 1. Simple GET (synchronous)
    public static String get(String url) throws Exception {
        HttpRequest request = HttpRequest.newBuilder(URI.create(url))
            .GET()
            .header("Accept", "application/json")
            .timeout(Duration.ofSeconds(5))
            .build();
        HttpResponse<String> response = client.send(request, BodyHandlers.ofString());
        if (response.statusCode() >= 400) throw new RuntimeException("HTTP " + response.statusCode());
        return response.body();
    }

    // 2. Async GET (non-blocking, returns CompletableFuture)
    public static CompletableFuture<String> getAsync(String url) {
        HttpRequest request = HttpRequest.newBuilder(URI.create(url))
            .GET().header("Accept", "application/json").build();
        return client.sendAsync(request, BodyHandlers.ofString())
            .thenApply(resp -> { if (resp.statusCode() >= 400) throw new RuntimeException("HTTP " + resp.statusCode()); return resp.body(); });
    }

    // 3. POST with JSON body
    public static String post(String url, String jsonBody, String bearerToken) throws Exception {
        HttpRequest request = HttpRequest.newBuilder(URI.create(url))
            .POST(BodyPublishers.ofString(jsonBody))
            .header("Content-Type", "application/json")
            .header("Authorization", "Bearer " + bearerToken)
            .build();
        HttpResponse<String> response = client.send(request, BodyHandlers.ofString());
        return response.body();
    }

    // 4. Parallel requests — fetch multiple URLs concurrently
    public static List<String> fetchAll(List<String> urls) throws Exception {
        List<CompletableFuture<String>> futures = urls.stream()
            .map(JavaHttpClient::getAsync)
            .toList();
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).toList())
            .get(30, TimeUnit.SECONDS);
    }

    // 5. Retry with exponential backoff
    public static CompletableFuture<String> getWithRetry(String url, int maxRetries) {
        return retryAsync(() -> getAsync(url), maxRetries, 1000);
    }

    @SuppressWarnings("unchecked")
    private static <T> CompletableFuture<T> retryAsync(java.util.function.Supplier<CompletableFuture<T>> action, int retriesLeft, long delayMs) {
        return action.get().exceptionallyCompose(ex -> {
            if (retriesLeft == 0) return CompletableFuture.failedFuture(ex);
            System.out.printf("Retry in %dms (%d left)%n", delayMs, retriesLeft);
            return CompletableFuture.delayedExecutor(delayMs, TimeUnit.MILLISECONDS)
                .execute(() -> {}); // delay trick
            // In practice: return after delay, re-invoke action
        });
    }

    public static void main(String[] args) throws Exception {
        // Async fire-and-forget demo
        getAsync("https://httpbin.org/get")
            .thenAccept(body -> System.out.println("Got: " + body.substring(0, 50)))
            .exceptionally(ex -> { System.err.println("Failed: " + ex.getMessage()); return null; })
            .join();
    }
}

package algorithms.dynamic_programming;

import java.util.*;

/**
 * Knapsack Variants and Custom Heap Operations — Java
 */
public class KnapsackAndHeap {

    // ---- 0/1 Knapsack (full table) ----
    public static int knapsack(int[] weights, int[] values, int W) {
        int n = weights.length;
        // 1D optimization — iterate backwards
        int[] dp = new int[W + 1];
        for (int i = 0; i < n; i++)
            for (int w = W; w >= weights[i]; w--)
                dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
        return dp[W];
    }

    // Reconstruct items in the knapsack
    public static List<Integer> knapsackItems(int[] weights, int[] values, int W) {
        int n = weights.length;
        int[][] dp = new int[n+1][W+1];
        for (int i = 1; i <= n; i++)
            for (int w = 0; w <= W; w++) {
                dp[i][w] = dp[i-1][w];
                if (weights[i-1] <= w) dp[i][w] = Math.max(dp[i][w], dp[i-1][w-weights[i-1]] + values[i-1]);
            }
        List<Integer> result = new ArrayList<>();
        int w = W;
        for (int i = n; i >= 1; i--)
            if (dp[i][w] != dp[i-1][w]) { result.add(i-1); w -= weights[i-1]; }
        return result;
    }

    // ---- Custom MinHeap ----
    static class MinHeap {
        private final int[] heap;
        private int size;
        MinHeap(int capacity) { heap = new int[capacity + 1]; }

        public void insert(int val) {
            heap[++size] = val;
            bubbleUp(size);
        }
        public int extractMin() {
            int min = heap[1];
            heap[1] = heap[size--];
            sinkDown(1);
            return min;
        }
        public int peek() { return heap[1]; }
        public boolean isEmpty() { return size == 0; }
        public int size() { return size; }

        private void bubbleUp(int i) {
            while (i > 1 && heap[i] < heap[i/2]) {
                int t = heap[i]; heap[i] = heap[i/2]; heap[i/2] = t;
                i /= 2;
            }
        }
        private void sinkDown(int i) {
            while (2*i <= size) {
                int child = 2*i;
                if (child < size && heap[child+1] < heap[child]) child++;
                if (heap[i] <= heap[child]) break;
                int t = heap[i]; heap[i] = heap[child]; heap[child] = t;
                i = child;
            }
        }
    }

    // ---- Top K elements using Java's PriorityQueue ----
    public static int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.merge(n, 1, Integer::sum);
        // Min-heap of size k
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        for (var e : freq.entrySet()) {
            heap.offer(new int[]{e.getKey(), e.getValue()});
            if (heap.size() > k) heap.poll();
        }
        int[] result = new int[k];
        for (int i = k-1; i >= 0; i--) result[i] = heap.poll()[0];
        return result;
    }

    public static void main(String[] args) {
        int[] weights = {2, 3, 4, 5};
        int[] values  = {3, 4, 5, 6};
        System.out.println(knapsack(weights, values, 8));  // 10
        System.out.println(knapsackItems(weights, values, 8)); // [2, 1] → items 2 and 1 (0-indexed)

        MinHeap heap = new MinHeap(10);
        for (int v : new int[]{5,3,8,1,2,7}) heap.insert(v);
        System.out.println(heap.extractMin()); // 1
        System.out.println(heap.extractMin()); // 2
        System.out.println(heap.peek());       // 3

        System.out.println(Arrays.toString(topKFrequent(new int[]{1,1,1,2,2,3}, 2))); // [1,2]
    }
}

package algorithms.searching;

import java.util.*;

/**
 * Spiral Matrix Problems in Java
 */
public class MatrixSpiral {

    // 1. Spiral traversal — O(m*n) time, O(1) space
    public static List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> result = new ArrayList<>();
        if (matrix.length == 0) return result;
        int top = 0, bottom = matrix.length - 1;
        int left = 0, right = matrix[0].length - 1;
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++)  result.add(matrix[top][c]);
            top++;
            for (int r = top; r <= bottom; r++)  result.add(matrix[r][right]);
            right--;
            if (top <= bottom) { for (int c = right; c >= left; c--) result.add(matrix[bottom][c]); bottom--; }
            if (left <= right) { for (int r = bottom; r >= top; r--) result.add(matrix[r][left]); left++; }
        }
        return result;
    }

    // 2. Generate n×n spiral matrix
    public static int[][] generateSpiral(int n) {
        int[][] matrix = new int[n][n];
        int top = 0, bottom = n-1, left = 0, right = n-1, num = 1;
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++)  matrix[top][c] = num++;
            top++;
            for (int r = top; r <= bottom; r++)  matrix[r][right] = num++;
            right--;
            if (top <= bottom) { for (int c = right; c >= left; c--) matrix[bottom][c] = num++; bottom--; }
            if (left <= right) { for (int r = bottom; r >= top; r--) matrix[r][left] = num++; left++; }
        }
        return matrix;
    }

    // 3. Rotate matrix 90 degrees clockwise — in-place
    public static void rotate90(int[][] matrix) {
        int n = matrix.length;
        // Step 1: Transpose
        for (int i = 0; i < n; i++)
            for (int j = i+1; j < n; j++) { int t = matrix[i][j]; matrix[i][j] = matrix[j][i]; matrix[j][i] = t; }
        // Step 2: Reverse each row
        for (int[] row : matrix) {
            int l = 0, r = n-1;
            while (l < r) { int t = row[l]; row[l++] = row[r]; row[r--] = t; }
        }
    }

    // 4. Diagonal traversal
    public static int[] findDiagonalOrder(int[][] matrix) {
        if (matrix.length == 0) return new int[0];
        int m = matrix.length, n = matrix[0].length;
        int[] result = new int[m * n];
        int idx = 0, d = 1; // d=1 going up-right, d=-1 going down-left
        int r = 0, c = 0;
        while (idx < m * n) {
            result[idx++] = matrix[r][c];
            int nr = r - d, nc = c + d;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                if (d == 1) { r += (c == n-1 ? 1 : 0); c += (c < n-1 ? 1 : 0); }
                else        { c += (r == m-1 ? 1 : 0); r += (r < m-1 ? 1 : 0); }
                d = -d;
            } else { r = nr; c = nc; }
        }
        return result;
    }

    // 5. Search in 2D sorted matrix — O(m+n)
    public static boolean searchMatrixII(int[][] matrix, int target) {
        int r = 0, c = matrix[0].length - 1;
        while (r < matrix.length && c >= 0) {
            if (matrix[r][c] == target) return true;
            if (matrix[r][c] > target) c--;
            else r++;
        }
        return false;
    }

    public static void main(String[] args) {
        int[][] m = {{1,2,3},{4,5,6},{7,8,9}};
        System.out.println(spiralOrder(m)); // [1,2,3,6,9,8,7,4,5]

        int[][] spiral = generateSpiral(4);
        for (int[] row : spiral) System.out.println(Arrays.toString(row));

        rotate90(m);
        for (int[] row : m) System.out.println(Arrays.toString(row)); // rotated
    }
}

package snippets.java.logging;

import org.slf4j.*;
import net.logstash.logback.argument.StructuredArguments;
import net.logstash.logback.marker.Markers;
import java.util.Map;

/**
 * Structured Logging in Java — SLF4J + Logback
 * JSON output for log aggregation (ELK, Datadog, Splunk)
 */
public class StructuredLogging {

    // Using LogstashEncoder for JSON output in logback.xml:
    // <appender name="JSON" class="ch.qos.logback.core.ConsoleAppender">
    //   <encoder class="net.logstash.logback.encoder.LogstashEncoder"/>
    // </appender>

    private static final Logger log = LoggerFactory.getLogger(StructuredLogging.class);

    // 1. Basic structured fields using StructuredArguments
    public static void basicStructured() {
        log.info("User logged in",
            StructuredArguments.kv("userId", 42),
            StructuredArguments.kv("email", "alice@example.com"),
            StructuredArguments.kv("duration_ms", 120)
        );
        // JSON output: {"message":"User logged in","userId":42,"email":"alice@example.com","duration_ms":120}
    }

    // 2. MDC (Mapped Diagnostic Context) — thread-local fields
    public static void withMDC(String requestId, String userId) {
        try (var mdc1 = org.slf4j.MDC.putCloseable("requestId", requestId);
             var mdc2 = org.slf4j.MDC.putCloseable("userId", userId)) {
            log.info("Processing request"); // requestId + userId auto-added to every log in this scope
            processOrder();
        } // MDC cleared automatically even on exception
    }
    private static void processOrder() {
        log.info("Order processed"); // also has requestId + userId in MDC
    }

    // 3. Structured markers (non-indexed fields, bulk JSON)
    public static void withMarkers(Map<String, Object> context) {
        log.info(Markers.appendEntries(context), "Request completed");
    }

    // 4. Error logging with exception details
    public static void logError(String operation, Exception ex, Map<String, String> ctx) {
        log.error("Operation failed: {}", operation,
            StructuredArguments.entries(ctx),
            ex // SLF4J renders full stack trace
        );
    }

    // 5. Log level guard (skip expensive serialization when off)
    public static void conditionalLog(Object expensiveObj) {
        if (log.isDebugEnabled()) {
            log.debug("State dump", StructuredArguments.kv("state", expensiveObj.toString()));
        }
    }

    // 6. Performance logging pattern
    public static <T> T measureAndLog(String operation, java.util.concurrent.Callable<T> task) throws Exception {
        long start = System.currentTimeMillis();
        try {
            T result = task.call();
            log.info("Operation succeeded",
                StructuredArguments.kv("operation", operation),
                StructuredArguments.kv("duration_ms", System.currentTimeMillis() - start));
            return result;
        } catch (Exception ex) {
            log.error("Operation failed",
                StructuredArguments.kv("operation", operation),
                StructuredArguments.kv("duration_ms", System.currentTimeMillis() - start), ex);
            throw ex;
        }
    }

    public static void main(String[] args) throws Exception {
        // Basic usage
        log.info("Server started",
            StructuredArguments.kv("port", 8080),
            StructuredArguments.kv("profile", "prod"));

        // MDC with request context
        withMDC("req-abc-123", "user-456");

        // Measure performance
        measureAndLog("db-query", () -> {
            Thread.sleep(50);
            return "result";
        });
    }
}

package snippets.java.concurrent;

import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

/**
 * CompletableFuture — Java's Answer to Promises
 * Equivalent to JS Promise.then/catch/finally/all/race/allSettled
 */
public class PromisePatterns {

    static CompletableFuture<String> fetchUser(int id) {
        return CompletableFuture.supplyAsync(() -> {
            if (id <= 0) throw new IllegalArgumentException("Invalid id");
            return "User-" + id;
        });
    }

    // 1. Chaining (.thenApply, .thenCompose, .thenAccept)
    public static void chainingDemo() {
        fetchUser(1)
            .thenApply(u -> u.toUpperCase())             // transform result
            .thenCompose(u -> CompletableFuture.supplyAsync(() -> u + "_ORDERS")) // flat-map
            .thenAccept(result -> System.out.println("Final: " + result))
            .exceptionally(ex -> { System.err.println("Error: " + ex.getMessage()); return null; })
            .join();
    }

    // 2. allOf — like Promise.all (wait for ALL)
    public static List<String> fetchAll(List<Integer> ids) {
        List<CompletableFuture<String>> futures = ids.stream().map(PromisePatterns::fetchUser).toList();
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).toList())
            .join();
    }

    // 3. anyOf — like Promise.race (first to complete wins)
    public static String race(List<CompletableFuture<String>> futures) {
        return (String) CompletableFuture.anyOf(futures.toArray(new CompletableFuture[0])).join();
    }

    // 4. allSettled — collect results AND errors
    public static List<String> allSettled(List<Integer> ids) {
        List<CompletableFuture<String>> futures = ids.stream()
            .map(id -> fetchUser(id)
                .exceptionally(ex -> "ERROR: " + ex.getMessage()))
            .toList();
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).toList())
            .join();
    }

    // 5. Retry with exponential backoff
    public static CompletableFuture<String> retry(int id, int maxAttempts, long baseDelayMs) {
        return fetchUser(id).exceptionallyCompose(ex -> {
            if (maxAttempts <= 0) return CompletableFuture.failedFuture(ex);
            System.out.printf("Retry in %dms (%d attempts left)%n", baseDelayMs, maxAttempts);
            return CompletableFuture.supplyAsync(() -> null,
                    CompletableFuture.delayedExecutor(baseDelayMs, TimeUnit.MILLISECONDS))
                .thenCompose(v -> retry(id, maxAttempts - 1, baseDelayMs * 2));
        });
    }

    // 6. Timeout
    public static CompletableFuture<String> withTimeout(CompletableFuture<String> future, long ms) {
        return future.orTimeout(ms, TimeUnit.MILLISECONDS) // Java 9+
            .exceptionally(ex -> ex instanceof TimeoutException ? "DEFAULT" : "ERROR");
    }

    // 7. Debounce (using ScheduledExecutorService)
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static ScheduledFuture<?> debounceTask;

    public static void debounce(Runnable action, long delayMs) {
        if (debounceTask != null && !debounceTask.isDone()) debounceTask.cancel(false);
        debounceTask = scheduler.schedule(action, delayMs, TimeUnit.MILLISECONDS);
    }

    public static void main(String[] args) throws Exception {
        chainingDemo();
        System.out.println(fetchAll(List.of(1, 2, 3)));             // [User-1, User-2, User-3]
        System.out.println(allSettled(List.of(1, -1, 3)));          // [User-1, ERROR:..., User-3]
        System.out.println(retry(1, 3, 100).get(5, TimeUnit.SECONDS)); // User-1
        scheduler.shutdown();
    }
}
